const readStates = `-- name: ReadStates :many
SELECT c.id AS channel_id,
       COALESCE(r.last_read_seq, 0)::bigint AS last_read,
       (SELECT COUNT(*) FROM group_messages m
        WHERE m.channel_id = c.id
          AND m.seq > COALESCE(r.last_read_seq, 0)
          AND m.deleted_at IS NULL
          AND m.author_id <> $1::uuid
          AND NOT (m.author_id = ANY($2::uuid[])))::bigint AS unread
FROM group_channels c
LEFT JOIN group_channel_reads r ON r.channel_id = c.id AND r.user_id = $1::uuid
WHERE c.id = ANY($3::uuid[])
`

type ReadStatesParams struct {
	UserID     uuid.UUID
	Hidden     []uuid.UUID
	ChannelIds []uuid.UUID
}

type ReadStatesRow struct {
	ChannelID uuid.UUID
	LastRead  int64
	Unread    int64
}

func (q *Queries) ReadStates(ctx context.Context, arg ReadStatesParams) ([]ReadStatesRow, error) {
	rows, err := q.db.Query(ctx, readStates, arg.UserID, arg.Hidden, arg.ChannelIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReadStatesRow{}
	for rows.Next() {
		var i ReadStatesRow
		if err := rows.Scan(&i.ChannelID, &i.LastRead, &i.Unread); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const readUpsert = `-- name: ReadUpsert :exec
INSERT INTO group_channel_reads (id, channel_id, user_id, last_read_seq, updated_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (channel_id, user_id) DO UPDATE
SET last_read_seq = GREATEST(group_channel_reads.last_read_seq, EXCLUDED.last_read_seq),
    updated_at = EXCLUDED.updated_at
`

type ReadUpsertParams struct {
	ID          uuid.UUID
	ChannelID   uuid.UUID
	UserID      uuid.UUID
	LastReadSeq int64
	UpdatedAt   time.Time
}

func (q *Queries) ReadUpsert(ctx context.Context, arg ReadUpsertParams) error {
	_, err := q.db.Exec(ctx, readUpsert,
		arg.ID,
		arg.ChannelID,
		arg.UserID,
		arg.LastReadSeq,
		arg.UpdatedAt,
	)
	return err
}

const readsDeleteForGroup = `-- name: ReadsDeleteForGroup :exec
DELETE FROM group_channel_reads
WHERE user_id = $1::uuid
  AND channel_id IN (SELECT id FROM group_channels WHERE group_id = $2::uuid)
`

type ReadsDeleteForGroupParams struct {
	UserID  uuid.UUID
	GroupID uuid.UUID
}

func (q *Queries) ReadsDeleteForGroup(ctx context.Context, arg ReadsDeleteForGroupParams) error {
	_, err := q.db.Exec(ctx, readsDeleteForGroup, arg.UserID, arg.GroupID)
	return err
}

const readsMarkGroupRead = `-- name: ReadsMarkGroupRead :exec

INSERT INTO group_channel_reads (id, channel_id, user_id, last_read_seq, updated_at)
SELECT gen_random_uuid(), c.id, $1::uuid, c.last_seq, $2::timestamptz
FROM group_channels c WHERE c.group_id = $3::uuid AND c.deleted_at IS NULL
ON CONFLICT (channel_id, user_id) DO UPDATE SET last_read_seq = EXCLUDED.last_read_seq, updated_at = EXCLUDED.updated_at
`

type ReadsMarkGroupReadParams struct {
	UserID  uuid.UUID
	Now     time.Time
	GroupID uuid.UUID
}

// ---- Read state -------------------------------------------------------------
// addMember: every live channel read up to now.
func (q *Queries) ReadsMarkGroupRead(ctx context.Context, arg ReadsMarkGroupReadParams) error {
	_, err := q.db.Exec(ctx, readsMarkGroupRead, arg.UserID, arg.Now, arg.GroupID)
	return err
}

const totalUnread = `-- name: TotalUnread :one
SELECT COUNT(*) AS unread
FROM group_members gm
JOIN groups g ON g.id = gm.group_id AND g.deleted_at IS NULL
JOIN group_channels c ON c.group_id = gm.group_id AND c.deleted_at IS NULL
LEFT JOIN group_channel_reads r ON r.channel_id = c.id AND r.user_id = gm.user_id
JOIN group_messages m ON m.channel_id = c.id AND m.seq > COALESCE(r.last_read_seq, 0)
WHERE gm.user_id = $1::uuid
  AND m.deleted_at IS NULL
  AND m.author_id <> $1::uuid
  AND NOT (m.author_id = ANY($2::uuid[]))
`

type TotalUnreadParams struct {
	UserID uuid.UUID
	Hidden []uuid.UUID
}

func (q *Queries) TotalUnread(ctx context.Context, arg TotalUnreadParams) (int64, error) {
	row := q.db.QueryRow(ctx, totalUnread, arg.UserID, arg.Hidden)
	var unread int64
	err := row.Scan(&unread)
	return unread, err
}
